CREATE TABLE IF NOT EXISTS `notification_campaign_rules` (`rule_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `scope_id` BIGINT UNSIGNED NOT NULL DEFAULT 0, `rule_key` VARCHAR(80) NOT NULL, `is_active` TINYINT NOT NULL DEFAULT 0, `title` VARCHAR(160) NOT NULL, `message` MEDIUMTEXT NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`rule_id`), UNIQUE KEY `uq_campaign_rule_scope` (`scope_id`, `rule_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
